const lessons=[{"title": "Di, ke and dari", "lang": "Malay", "level": "A1", "kind": "Grammar", "pages": [{"label": "日本語", "lines": ["di は場所、ke は行き先、dari は出発点を表します。駅名の前に置きます。"], "index": 0}, {"label": "Bahasa Melayu", "lines": ["Di: tempat sekarang. Ke: tempat kita pergi. Dari: tempat kita mula."], "index": 1}, {"label": "English", "lines": ["Use di for location, ke for destination and dari for starting point."], "index": 2}, {"label": "1 · Notice", "lines": ["Saya di KL Sentral.", "Saya nak pergi ke Pasar Seni.", "Saya naik tren dari KL Sentral.", "Cari nama tempat. Di mana saya sekarang?"], "index": 3}, {"label": "2 · Choose", "lines": ["Pilih: di / ke / dari.", "Saya sekarang ____ rumah.", "Saya nak pergi ____ kelas.", "Saya naik bas ____ rumah ke kampus."], "index": 4}, {"label": "3 · Make your own", "lines": ["Anda di stesen. Pilih tempat yang anda nak pergi.", "Beritahu kawan: anda di mana? Nak pergi ke mana? Dari mana?", "________________________________", "________________________________"], "index": 5}, {"label": "Teacher key", "lines": ["Stage 2: di / ke / dari.", "Accept equivalent descriptions with different places. Check that direction and starting point are clear."], "index": 6}]}, {"title": "Plans and arrangements", "lang": "English", "level": "B1", "kind": "Grammar", "pages": [{"label": "日本語", "lines": ["その場の決定には will、前からの意図には going to、約束済みの予定には現在進行形が使えます。文脈によって複数の表現が可能です。"], "index": 7}, {"label": "Bahasa Melayu", "lines": ["Guna will untuk keputusan spontan, going to untuk niat, dan present continuous untuk janji yang sudah diatur. Lihat konteks."], "index": 8}, {"label": "English", "lines": ["Use will for a decision made now, going to for an intention, and the present continuous for an arrangement. Context can allow more than one form."], "index": 9}, {"label": "1 · Notice", "lines": ["The phone rings: “I’ll answer it.”", "You have a plan: “I’m going to call the clinic.”", "The clinic has confirmed: “I’m seeing the dentist on Friday.”", "Which sentence suggests another person knows about the plan?"], "index": 10}, {"label": "2 · Choose", "lines": ["The receptionist offers 3 pm. Decide now: “Thanks, I ____ take it.”", "Tell your friend about the confirmed booking: “I ____ seeing the dentist at three.”", "Explain how the situation changed."], "index": 11}, {"label": "3 · Improvise", "lines": ["Tell a partner about an intention and a fixed appointment.", "Your partner asks for help tomorrow. Decide what you can do. Say it aloud.", "________________________________", "________________________________"], "index": 12}, {"label": "Teacher key", "lines": ["Stage 1: the confirmed appointment.", "Stage 2: will (or ’ll) / am.", "Accept going to for an intended visit when the sentence is reformulated. Ask what the speaker wants to emphasise."], "index": 13}]}, {"title": "A clear pickup message", "lang": "Malay", "level": "A2", "kind": "Writing", "pages": [{"label": "日本語", "lines": ["迎えの依頼では、時刻と場所を伝えます。相手との関係によって頼み方を選びましょう。"], "index": 14}, {"label": "Bahasa Melayu", "lines": ["Tulis masa dan tempat. Guna “boleh” untuk minta tolong."], "index": 15}, {"label": "English", "lines": ["Give a time and place. Use boleh to make a request."], "index": 16}, {"label": "1 · Compare", "lines": ["A   Jumpa pukul tiga di pintu A, ya.", "B   Boleh ambil saya di pintu A pukul tiga? Terima kasih.", "C   Ambil saya dekat sana nanti.", "Yang mana sesuai kalau kawan dah tahu rancangan anda? Yang mana jelas untuk minta tolong?"], "index": 17}, {"label": "2 · Repair", "lines": ["Kawan anda tak tahu tempat atau masa. Baiki mesej C.", "Tempat: pintu B. Masa: pukul empat petang.", "________________________________", "________________________________"], "index": 18}, {"label": "3 · Write", "lines": ["Kelas tamat lewat. Minta kawan datang pukul lima. Pilih tempat baru.", "Tulis mesej. Tukar dengan kawan. Boleh dia cari anda?", "________________________________", "________________________________"], "index": 19}, {"label": "Teacher key", "lines": ["A confirms an existing plan. B makes a request. C leaves the reader guessing.", "Example: Boleh ambil saya di pintu B pukul empat petang?"], "index": 20}]}, {"title": "Request figures by Thursday", "lang": "English", "level": "B1", "kind": "Writing", "pages": [{"label": "日本語", "lines": ["期限、必要な資料、依頼の理由を明確にします。相手が次に何をすればよいか確認しましょう。"], "index": 21}, {"label": "Bahasa Melayu", "lines": ["Nyatakan bahan yang anda perlu, sebab dan tarikh akhir. Semak sama ada pembaca tahu apa yang perlu dibuat."], "index": 22}, {"label": "English", "lines": ["Give the item, reason and deadline. Choose a tone that suits the reader."], "index": 23}, {"label": "1 · Compare", "lines": ["A   Please send the sales figures by noon on Thursday for Friday’s report.", "B   I’m putting Friday’s report together. Could you send the sales figures by noon on Thursday? Let me know if you need more time.", "C   Just following up on those numbers. I need them soon.", "Underline the deadline. Which message invites a reply about timing?"], "index": 24}, {"label": "2 · Repair", "lines": ["Rewrite C for a colleague you know well.", "Include the sales figures, Thursday at noon, and the purpose.", "________________________________", "________________________________"], "index": 25}, {"label": "3 · Write", "lines": ["A supplier has the delivery figures you need for a Monday meeting. Choose a realistic deadline.", "Write your request. Ask your partner to identify the next action and deadline.", "________________________________", "________________________________"], "index": 26}, {"label": "Teacher key", "lines": ["A and B give a deadline. B explicitly invites a reply. C leaves both the item and timing unclear.", "Accept direct or warmer phrasing when the request, purpose and deadline are clear."], "index": 27}]}, {"title": "Lunch at a Malaysian stall", "lang": "Malay", "level": "A2", "kind": "Conversation", "pages": [{"label": "日本語", "lines": ["「Nak …」で注文します。dah habis は売り切れ、bungkus は持ち帰り。予算を伝え、別の料理や飲み物を相談しましょう。"], "index": 28}, {"label": "Bahasa Melayu", "lines": ["Nak untuk pesan makanan. Dah habis: tiada lagi. Baki: wang yang dapat balik. Tanya harga dan semak pesanan."], "index": 29}, {"label": "English", "lines": ["Use nak to order, dah habis for sold out and bungkus for takeaway. Ask about price, choose another dish and check your change."], "index": 30}, {"label": "1 · 1. Pesan makan", "lines": ["A   Nak nasi ayam satu. Ada lagi?", "B   Ada. Nak makan sini ke bungkus?", "A   Makan sini. Kawan saya pun nak makan.", "B   Dia nak nasi ayam juga?", "A   Dia tak makan ayam. Ada mi goreng?", "B   Ada. Nak satu pinggan?", "A   Ya. Mi tu pedas tak?", "B   Tak pedas. Sambal ada di tepi."], "index": 31}, {"label": "1 · 2. Pilih minuman", "lines": ["A   Air apa yang ada hari ni?", "B   Ada teh ais, kopi dan air kosong.", "A   Teh ais satu. Boleh kurang manis?", "B   Boleh. Kawan nak minum apa?", "A   Dia nak air kosong. Berapa harga teh ais?", "B   Tiga ringgit. Air kosong satu ringgit.", "A   Kalau dua air kosong saja?", "B   Dua ringgit. Nak tukar?", "A   Ya, dua air kosong saja.", "B   Baik. Nak ais?", "A   Satu dengan ais, satu lagi tak nak ais.", "B   Baik, saya ambil sekarang."], "index": 32}, {"label": "1 · 3. Semak dan bayar", "lines": ["A   Maaf, mi goreng belum sampai. Dah siap?", "B   Sekejap ya. Ini mi goreng. Cukup semua?", "A   Ya. Nasi ayam, mi goreng dan dua air kosong.", "B   Betul. Nasi lapan, mi enam, air dua. Semua enam belas.", "A   Boleh bayar dengan kad?", "B   Maaf, tunai atau QR saja.", "A   Kalau saya bagi dua puluh ringgit, ada baki?", "B   Ada. Ini baki empat ringgit.", "A   Terima kasih. Sambal boleh ambil di mana?", "B   Di hujung meja, dekat sudu."], "index": 33}, {"label": "2 · 1. Tanya pilihan", "lines": ["A   Nak nasi lemak satu. Ada lagi?", "B   Maaf, nasi lemak dah ____.", "A   Kalau macam tu, ada apa ____?", "B   Ada nasi ayam dan mi goreng.", "A   Mi goreng ____ tak?", "B   Pedas sikit. Nak cuba nasi ayam?", "A   Ya. Kalau nak sambal asing, boleh?", "B   ____. Nak makan sini atau bungkus?"], "index": 34}, {"label": "2 · 2. Semak bajet", "lines": ["A   Saya nak ____. Nasi ayam berapa?", "B   Lapan ringgit. Nak air juga?", "A   Saya ada sepuluh ringgit. Air apa yang boleh saya beli?", "B   Air kosong dua ringgit. Teh ais tiga ringgit.", "A   Kalau ambil air kosong, cukup tak?", "B   ____. Semua sepuluh ringgit.", "A   Baik. Air kosong satu, tak nak ais.", "B   Baik. Nak sudu sekali?"], "index": 35}, {"label": "2 · 3. Ambil pesanan", "lines": ["A   Ya, satu sudu. Saya tunggu di ____?", "B   Di tepi kaunter. Saya panggil nanti.", "A   Maaf, yang ini nasi saya ke?", "B   Ya. Cuba tengok, cukup semua?", "A   Air belum ada. Boleh saya ambil sekarang?", "B   Boleh. Ini air kosong. Nak bayar macam mana?", "A   Boleh bayar dengan ____?", "B   Boleh. Terima kasih, jumpa lagi."], "index": 36}, {"label": "3 · Role A", "lines": ["Bual selama 3–5 minit. Kalau siap awal, tukar satu pilihan dan tanya lagi.", "Ada RM10. Nak nasi lemak dan air. Tanya apa lagi yang ada dan bandingkan harga.", "Kawan tak nak makanan pedas. Tanya pasal sambal. Pesan, semak harga dan cara bayar.", "Tiba-tiba kawan nak bungkus. Apa perlu tukar?", "________________________________", "________________________________"], "index": 37}, {"label": "3 · Role B", "lines": ["Bual selama 3–5 minit. Kalau siap awal, tukar satu pilihan dan tanya lagi.", "Nasi lemak dah habis. Nasi ayam RM8, mi goreng RM6, air kosong RM2. Teh ais RM3.", "Tanya pasal sambal, ais dan makan sini atau bungkus. Terima tunai atau QR.", "Bila pelanggan semak pesanan, satu minuman belum siap. Cari jalan sama-sama.", "________________________________", "________________________________"], "index": 38}, {"label": "Teacher key", "lines": ["Guided answers in order: habis / lagi / pedas / Boleh / bungkus / Cukup / mana / kad.", "Allow equivalent natural answers. For each stage, play all three scenes as one conversation. Aim for 3–5 minutes per pair. If reading ends early, cover the script and negotiate a change before finishing.", "Check that both partners ask a question, respond to a new detail and confirm the outcome."], "index": 39}]}, {"title": "Finding the right platform", "lang": "English", "level": "A1", "kind": "Conversation", "pages": [{"label": "日本語", "lines": ["Where is …? で場所を聞き、On the left? のように方向を繰り返して確認します。lift はエレベーターです。"], "index": 40}, {"label": "Bahasa Melayu", "lines": ["Tanya tempat dengan Where is …? Ulang arah untuk semak. Lift ialah lif."], "index": 41}, {"label": "English", "lines": ["Ask Where is …? Repeat the direction to check it. Ask What time …? for the next train."], "index": 42}, {"label": "1 · 1. Find the platform", "lines": ["A   Excuse me. Where is platform two?", "B   It’s on the left. Where are you going?", "A   To Park Road. Is this the right train?", "B   Yes. Do you have a ticket?", "A   Yes. Is this ticket for one person?", "B   Let me see. Yes, one adult.", "A   Do I go through this gate?", "B   Yes. Put your ticket here."], "index": 43}, {"label": "1 · 2. Choose a route", "lines": ["A   I have a big bag. Are there stairs?", "B   Yes. There’s a lift too. Do you want the lift?", "A   Yes, please. Is it near the gate?", "B   It’s next to the shop. Can you see the sign?", "A   The blue sign on the right?", "B   That’s the toilet. Look on the left.", "A   Oh, next to the coffee shop?", "B   Yes. Take the lift down one floor."], "index": 44}, {"label": "1 · 3. Check the time", "lines": ["A   What time is the next train?", "B   At ten past two. What time is it now?", "A   Five past two. Do I have time?", "B   Yes. It’s two minutes to the platform.", "A   And if I miss it?", "B   There’s another train at two twenty.", "A   So I take the lift down and go to platform two?", "B   Yes. Check the screen for Park Road.", "A   Thank you. Is there a lift at Park Road too?", "B   Yes. It’s near the exit."], "index": 45}, {"label": "2 · 1. Find the gate", "lines": ["A   Excuse me. ____ is platform three?", "B   It’s over there. Where do you want to go?", "A   To Lake Street. Is this the right gate?", "B   Yes. Have you got a ticket?", "A   No. Where can I buy one?", "B   At the machine on the ____.", "A   Can I pay by card?", "B   Yes. Tap your card here."], "index": 46}, {"label": "2 · 2. Find a lift", "lines": ["A   Thanks. Are there stairs to the platform?", "B   Yes. Do you need the ____?", "A   Yes. I have two bags. Is it near here?", "B   It’s next to the ticket office.", "A   Is that the office on the left?", "B   Yes. Take the lift up one floor.", "A   Up ____ floor, then platform three?", "B   That’s right. Follow the signs."], "index": 47}, {"label": "2 · 3. Check the train", "lines": ["A   What ____ is the next train?", "B   At nine fifteen. It’s nine ten now.", "A   Five minutes. Is the platform far?", "B   No. You have time. Look at the screen upstairs.", "A   What name do I look for?", "B   Lake Street. Where are you getting off?", "A   At Lake Street. Which exit is near the bus stop?", "B   Exit B. The buses are outside."], "index": 48}, {"label": "3 · Role A", "lines": ["Talk for 3–5 minutes. If you agree early, change one detail and work out a new plan.", "You need a ticket to Lake Street. You have two heavy bags. Ask for the platform, price and lift.", "You want to arrive by ten. Ask when two trains leave and arrive. Choose one.", "You lose sight of the lift. Call back and describe what you see.", "________________________________", "________________________________"], "index": 49}, {"label": "3 · Role B", "lines": ["Talk for 3–5 minutes. If you agree early, change one detail and work out a new plan.", "Lake Street: platform four, RM3. The lift is behind the shop. Ask what the traveller can see.", "Trains leave at 9:35 and 9:50. The journey takes 15 minutes. Help your partner choose.", "The shop is closed. Give a second landmark and check the traveller knows the way.", "________________________________", "________________________________"], "index": 50}, {"label": "Teacher key", "lines": ["Guided answers in order: Where / right / lift / one / time.", "Allow equivalent natural answers. For each stage, play all three scenes as one conversation. Aim for 3–5 minutes per pair. If reading ends early, cover the script and negotiate a change before finishing.", "Check that both partners ask a question, respond to a new detail and confirm the outcome."], "index": 51}]}, {"title": "Set a new meeting time", "lang": "English", "level": "B1", "kind": "Conversation", "pages": [{"label": "日本語", "lines": ["Would … work? で都合を尋ねます。代案とその理由を伝え、誰が何をするか最後に確認しましょう。"], "index": 52}, {"label": "Bahasa Melayu", "lines": ["Guna Would … work? untuk tanya masa yang sesuai. Bincang pilihan, sebab dan tugas masing-masing."], "index": 53}, {"label": "English", "lines": ["Use Would … work? to check a suggestion. Compare two options and confirm who will follow up."], "index": 54}, {"label": "1 · 1. Explain the change", "lines": ["A   Can we move Monday’s meeting? A client wants a site visit.", "B   What time do you need to leave?", "A   By nine. I should be back by noon, traffic permitting.", "B   Could we meet at twelve thirty, then?", "A   I’d rather allow for a delay. Is your afternoon free?", "B   I’m interviewing someone at two. How long do we need?", "A   About forty minutes if we read the figures first.", "B   That sounds reasonable. Let me check Tuesday as well."], "index": 55}, {"label": "1 · 2. Compare options", "lines": ["A   Would Tuesday at ten work better for you?", "B   I’m at the branch until three. Could you do four?", "A   Possibly. What do we need to decide before Wednesday?", "B   The supplier needs our numbers by lunchtime.", "A   Then four gives us enough time. Where shall we meet?", "B   The small meeting room is quiet. Is it available?", "A   I’ll check. It’s booked, but the training room is free.", "B   Let’s take that. Can the branch team join online?"], "index": 56}, {"label": "1 · 3. Agree on next steps", "lines": ["A   Yes. Shall I add a video link to the invitation?", "B   Please do. Could you send the figures beforehand too?", "A   I have last month’s totals. Do you need the forecast?", "B   Yes, the supplier will ask about next month.", "A   I can send both by Tuesday morning. Who will brief Mei?", "B   I’ll call her today. So we’re meeting on Tuesday at four?", "A   Yes, in the training room, with the branch team online.", "B   Great. I’ll look out for your updated invitation."], "index": 57}, {"label": "2 · 1. Explain a clash", "lines": ["A   Could we ____ our Thursday workshop? My train was cancelled.", "B   Of course. Would the afternoon ____ for you?", "A   I can get there by three, but I leave again at four.", "B   How long do we need for the workshop?", "A   An hour and a half. Could we try Friday instead?", "B   Perhaps. Do all the trainees need to attend in person?", "A   They need to practise with the equipment.", "B   Then let’s find a time when everyone can come."], "index": 58}, {"label": "2 · 2. Compare alternatives", "lines": ["A   How ____ Friday morning at nine?", "B   Two people have training until ten. What about eleven?", "A   The room is free then. Shall I reserve it until half past twelve?", "B   Yes, please. Is there time to set everything up?", "A   I can get there early if you send me the checklist.", "B   Would tonight be early enough?", "A   Yes. Who can bring the spare equipment?", "B   I’ll ask the technician before I go home."], "index": 59}, {"label": "2 · 3. Confirm responsibilities", "lines": ["A   Shall I ____ the revised invitation?", "B   Yes. Could you explain why we moved it?", "A   I’ll mention the travel delay. Anything else to include?", "B   Ask everyone to bring their practice notes.", "A   So that’s Friday at ____, in the original room?", "B   Correct. You’ll send the invitation and I’ll bring the checklist.", "A   I thought you were sending me the checklist tonight.", "B   You’re right. I’ll send it tonight and bring a copy on Friday."], "index": 60}, {"label": "3 · Role A", "lines": ["Talk for 3–5 minutes. If you agree early, change one detail and work out a new plan.", "A client needs you on Monday morning. Tuesday after three is possible. Explain why the team needs 45 minutes together.", "Your branch manager can only attend online. Ask about the room and equipment. Agree who will send the figures.", "A late message moves your client visit. Decide whether to change the plan again.", "________________________________", "________________________________"], "index": 61}, {"label": "3 · Role B", "lines": ["Talk for 3–5 minutes. If you agree early, change one detail and work out a new plan.", "Your Monday afternoon is full. Offer Tuesday morning first, then Tuesday at four. Find out why everyone needs to attend.", "The small room has no video screen. Offer the training room. Ask for the figures before the meeting.", "Confirm the time, who will send the link and who will brief anyone absent.", "________________________________", "________________________________"], "index": 62}, {"label": "Teacher key", "lines": ["Guided answers in order: move / work / about / send / eleven.", "Allow equivalent natural answers. For each stage, play all three scenes as one conversation. Aim for 3–5 minutes per pair. If reading ends early, cover the script and negotiate a change before finishing.", "Check that both partners ask a question, respond to a new detail and confirm the outcome."], "index": 63}]}, {"title": "Meeting at the station", "lang": "Japanese", "level": "A2", "kind": "Conversation", "pages": [{"label": "日本語", "lines": ["待ち合わせ（まちあわせ）：会う時間と場所を決めます。「近くに何がありますか」で目印を聞きます。改札（かいさつ）は駅の出入口にあります。"], "index": 64}, {"label": "Bahasa Melayu", "lines": ["Gunakan 今、どこですか untuk tanya lokasi. 目印（めじるし） ialah tanda yang mudah dilihat. Semak pintu keluar dan tempat menunggu."], "index": 65}, {"label": "English", "lines": ["Ask 今、どこですか (Where are you now?) and 近くに何がありますか (What is nearby?). 改札（かいさつ） is a ticket gate. Suggest a landmark and confirm it."], "index": 66}, {"label": "1 · 1. 待ち合わせの場所", "lines": ["A   もしもし。今、どこですか。", "B   駅に着きました。今、改札の前です。", "A   改札は二つあります。近くに何がありますか。", "B   パン屋があります。右に小さな花屋もあります。", "A   あ、それは東口ですね。私は西口にいます。", "B   西口ですか。ここから遠いですか。", "A   歩いて五分くらいです。荷物は多いですか。", "B   はい、大きいかばんが二つあります。"], "index": 67}, {"label": "1 · 2. 行き方を相談する", "lines": ["A   そちらに行きましょうか。", "B   お願いします。階段はちょっと大変です。", "A   では東口で会いましょう。座る場所はありますか。", "B   はい、パン屋の前にベンチがあります。", "A   そこは人が多いですか。", "B   ええ。花屋の横にもベンチがありますよ。", "A   じゃあ、花屋の横にしませんか。", "B   いいですね。そこで待っています。"], "index": 68}, {"label": "1 · 3. 目印を確認する", "lines": ["A   花屋の近くに着きました。何色のかばんですか。", "B   大きい青いかばんです。今、どこにいますか。", "A   赤い看板の前です。ベンチが見えません。", "B   あ、看板の後ろですよ。私は白い帽子をかぶっています。", "A   見えました。手を上げてもらえますか。", "B   はい。分かりますか。", "A   分かりました。お待たせしました。お昼はもう食べましたか。", "B   まだです。荷物を預けてから、一緒に食べませんか。"], "index": 69}, {"label": "2 · 1. 場所を聞く", "lines": ["A   もしもし。今、____ですか。", "B   バス停の前です。駅はどちらですか。", "A   近くに何が____か。", "B   コンビニがあります。向かいに銀行があります。", "A   それなら南口ですね。北口まで来られますか。", "B   歩いて何分くらいですか。", "A   十分くらいです。道は分かりますか。", "B   いいえ。行き方を教えてください。"], "index": 70}, {"label": "2 · 2. 別の場所を提案する", "lines": ["A   まず銀行の前を通ってください。", "B   すみません、雨が強くなりました。", "A   じゃあ、コンビニで____いてください。", "B   ありがとうございます。入口でいいですか。", "A   入口は寒いでしょう。店の中に座る場所はありますか。", "B   はい、窓のそばにテーブルがあります。", "A   では、そこにしましょう。何か飲みますか。", "B   温かいお茶をお願いします。"], "index": 71}, {"label": "2 · 3. 相手を見つける", "lines": ["A   コンビニに着きました。窓の____にいますか。", "B   はい。黒いコートを着ています。", "A   テーブルが二つありますね。どちらですか。", "B   奥のテーブルです。手を上げますね。", "A   あ、分かりました。お茶をどうぞ。", "B   ありがとうございます。雨はまだ強いですか。", "A   少し弱くなりました。駅まで一緒に歩きませんか。", "B   そうですね。お茶を飲んでから行きましょう。"], "index": 72}, {"label": "3 · Role A", "lines": ["3〜5分話しましょう。早く終わったら、条件を一つ変えて相談を続けましょう。", "東口にいます。友達は別の出口にいます。今いる場所と近くの店を聞いてください。", "大きな荷物があります。階段を使わずに会える場所を相談してください。", "雨が降ってきました。待つ場所を変えて、服やかばんの色を伝えてください。", "________________________________", "________________________________"], "index": 73}, {"label": "3 · Role B", "lines": ["3〜5分話しましょう。早く終わったら、条件を一つ変えて相談を続けましょう。", "西口にいます。東口にはパン屋と花屋があります。相手に近くの店を聞いてください。", "ベンチは外にあります。店の中でも待てます。相手の荷物について聞いてください。", "同じ色のかばんが二つ見えます。別の目印を聞いて、会った後の予定を決めてください。", "________________________________", "________________________________"], "index": 74}, {"label": "Teacher key", "lines": ["Guided answers in order: どこ / あります / 待って / そば.", "Allow equivalent natural answers. For each stage, play all three scenes as one conversation. Aim for 3–5 minutes per pair. If reading ends early, cover the script and negotiate a change before finishing.", "Check that both partners ask a question, respond to a new detail and confirm the outcome."], "index": 75}]}, {"title": "Where things are · に and で", "lang": "Japanese", "level": "A1", "kind": "Grammar", "pages": [{"label": "日本語", "lines": ["「に」は人や物がある場所、「で」は何かをする場所です。"], "index": 76}, {"label": "Bahasa Melayu", "lines": ["Guna に untuk lokasi dengan あります. Guna で untuk tempat sesuatu aktiviti berlaku."], "index": 77}, {"label": "English", "lines": ["With あります, に marks where something is. With an action such as 読みます, で marks where you do it."], "index": 78}, {"label": "1 · Notice", "lines": ["ロビーに本があります。", "ロビーで本を読みます。", "どちらの文で、人が何かをしますか。"], "index": 79}, {"label": "2 · Choose", "lines": ["に・で を入れましょう。", "駅の前＿＿店があります。", "その店＿＿パンを買います。", "部屋＿＿机があります。"], "index": 80}, {"label": "3 · Write and ask", "lines": ["家や学校に何がありますか。そこで何をしますか。", "二つの文を書いて、相手にも聞きましょう。", "________________________________", "________________________________"], "index": 81}, {"label": "Teacher key", "lines": ["Second model describes an action. Gaps: に / で / に.", "Example: 学校に図書室があります。図書室で本を読みます。"], "index": 82}]}, {"title": "Tell a colleague you will be late", "lang": "Japanese", "level": "B1", "kind": "Writing", "pages": [{"label": "日本語", "lines": ["到着予定と次にしてほしいことを伝えます。相手との関係に合う言い方を選びましょう。"], "index": 83}, {"label": "Bahasa Melayu", "lines": ["Nyatakan waktu tiba dan apa yang rakan boleh buat sementara menunggu."], "index": 84}, {"label": "English", "lines": ["State the expected arrival time and whether the recipient should wait or start."], "index": 85}, {"label": "1 · Compare", "lines": ["A　ごめん、電車が遅れてる。10時10分ごろ着くよ。先に始めてて。", "B　すみません。電車の遅れで、到着は10時10分ごろになります。先に始めていただけますか。", "C　少し遅れます。すみません。", "どれを親しい同僚に送りますか。Cを読んだ相手は何を聞きたいですか。"], "index": 86}, {"label": "2 · Repair", "lines": ["Cを書き直しましょう。到着は9時15分です。会議は先に始めてください。", "________________________________", "________________________________"], "index": 87}, {"label": "3 · Write", "lines": ["取引先との約束に遅れます。理由と到着予定を伝え、相手の都合を聞いてください。", "________________________________", "________________________________"], "index": 88}, {"label": "Teacher key", "lines": ["A is casual, B is appropriate for a more formal relationship. C leaves the recipient unsure whether to wait.", "Example: 申し訳ありません。電車が遅れており、9時15分に到着予定です。先に始めていただけますか。"], "index": 89}]}];
